const paymentLabels: Record<string, string> = { pix: "Pix", cash: "Dinheiro", credit_card: "Crédito", debit_card: "Débito", transfer: "Transferência", other: "Outro", receivable: "A receber" };
const statusLabels: Record<string, string> = { completed: "Concluída", pending: "Pendente", cancelled: "Cancelada", paid: "Pago", draft: "Rascunho", sent: "Enviado", approved: "Aprovado", converted: "Convertido" };

type Product = { id: string; company_id: string; category_id: string | null; name: string; barcode: string | null; sku: string | null; description: string | null; cost_price: number; sale_price: number; stock: number; minimum_stock: number; supplier_name: string | null; is_active: boolean; updated_at: string; };
type Customer = { id: string; company_id: string; name: string; phone: string | null; whatsapp: string | null; email: string | null; address: string | null; address_number: string | null; city: string | null; state: string | null; tax_id: string | null; notes: string | null; is_active: boolean; };
type Sale = { id: string; sale_number: number; customer_id: string | null; status: string; payment_method: string; total: number; created_at: string; customers?: { name: string } | null };
type Finance = { id: string; type: string; category: string; description: string | null; amount: number; status: string; occurred_at: string; };
type Quote = { id: string; quote_number: number; customer_id: string | null; status: string; subtotal: number; discount: number; total: number; notes: string | null; created_at: string; customers?: { name: string } | null };
type Company = { id: string; name: string; phone: string | null; whatsapp: string | null; address: string | null; address_number: string | null; city: string | null; state: string | null; zip_code: string | null; tax_id: string | null; notes: string | null; allow_negative_stock: boolean; };
type CartItem = { productId: string; name: string; barcode: string | null; costPrice: number; quantity: number; unitPrice: number; discountType: "fixed" | "percent"; discountValue: number; };

const asNumber = (value: string | number | null | undefined) => Number(value || 0);
const itemDiscount = (item: CartItem) => item.discountType === "percent" ? item.quantity * item.unitPrice * Math.min(100, Math.max(0, item.discountValue)) / 100 : Math.min(item.quantity * item.unitPrice, Math.max(0, item.discountValue));
const itemTotal = (item: CartItem) => Math.max(0, item.quantity * item.unitPrice - itemDiscount(item));
const initials = (name: string) => name.split(" ").map((part) => part[0]).slice(0, 2).join("").toUpperCase();

function downloadReportPdf(company: Company, products: Product[], sales: Sale[], finance: Finance[], customers: Customer[]) {
  const doc = new jsPDF({ unit: "mm", format: "a4" });
  const generatedAt = new Date();
  const safeCompanyName = company.name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "empresa";
  let y = 18;
  doc.setTextColor(14, 79, 80);
  doc.setFontSize(20);
  doc.setFont("helvetica", "bold");
  doc.text("Relatório completo da operação", 14, y);
  y += 8;
  doc.setFontSize(11);
  doc.setFont("helvetica", "normal");
  doc.text(company.name, 14, y);
  doc.setTextColor(100, 116, 139);
  doc.setFontSize(9);
  doc.text("Gerado em " + dateTime(generatedAt.toISOString()), 14, y + 6);
  y += 16;

  const activeSales = sales.filter((sale) => sale.status !== "cancelled");
  const revenue = activeSales.reduce((sum, sale) => sum + asNumber(sale.total), 0);
  const income = finance.filter((item) => item.type === "income" && item.status !== "cancelled").reduce((sum, item) => sum + asNumber(item.amount), 0);
  const expenses = finance.filter((item) => item.type === "expense" && item.status !== "cancelled").reduce((sum, item) => sum + asNumber(item.amount), 0);
  autoTable(doc, {
    startY: y,
    head: [["Indicador", "Valor"]],
    body: [
      ["Faturamento", money(revenue)],
      ["Vendas válidas", String(activeSales.length)],
      ["Ticket médio", money(activeSales.length ? revenue / activeSales.length : 0)],
      ["Entradas", money(income)],
      ["Saídas", money(expenses)],
      ["Resultado", money(income - expenses)],
      ["Produtos ativos", String(products.filter((product) => product.is_active).length)],
      ["Clientes", String(customers.length)],
    ],
    theme: "grid",
    headStyles: { fillColor: [14, 113, 107] },
    styles: { fontSize: 8 },
  });
  y = ((doc as jsPDF & { lastAutoTable?: { finalY: number } }).lastAutoTable?.finalY || y) + 10;

  const addSection = (title: string, head: string[], body: string[][]) => {
    if (y > 265) { doc.addPage(); y = 18; }
    doc.setTextColor(14, 79, 80);
    doc.setFontSize(13);
    doc.setFont("helvetica", "bold");
    doc.text(title, 14, y);
    autoTable(doc, { startY: y + 4, head: [head], body, theme: "grid", headStyles: { fillColor: [14, 113, 107] }, styles: { fontSize: 7, cellPadding: 2 }, margin: { left: 14, right: 14 } });
    y = ((doc as jsPDF & { lastAutoTable?: { finalY: number } }).lastAutoTable?.finalY || y) + 10;
  };

  addSection("Vendas", ["Número", "Data", "Cliente", "Pagamento", "Status", "Total"], sales.map((sale) => [
    "#" + sale.sale_number,
    dateTime(sale.created_at),
    sale.customers?.name || "Consumidor final",
    paymentLabels[sale.payment_method] || sale.payment_method,
    statusLabels[sale.status] || sale.status,
    money(sale.total),
  ]));
  addSection("Produtos", ["Produto", "Código", "Preço", "Estoque", "Status"], products.map((product) => [
    product.name,
    product.barcode || product.sku || "—",
    money(product.sale_price),
    String(product.stock),
    product.is_active ? "Ativo" : "Inativo",
  ]));
  addSection("Financeiro", ["Data", "Tipo", "Descrição", "Categoria", "Status", "Valor"], finance.map((item) => [
    dateOnly(item.occurred_at),
    item.type === "income" ? "Entrada" : "Saída",
    item.description || "Sem descrição",
    item.category,
    statusLabels[item.status] || item.status,
    money(item.amount),
  ]));
  addSection("Clientes", ["Nome", "E-mail", "Telefone", "Documento", "Cidade"], customers.map((customer) => [
    customer.name,
    customer.email || "—",
    customer.whatsapp || customer.phone || "—",
    customer.tax_id || "—",
    customer.city ? customer.city + (customer.state ? " / " + customer.state : "") : "—",
  ]));
  doc.save("relatorio-" + safeCompanyName + "-" + generatedAt.toISOString().slice(0, 10) + ".pdf");
}

function EmptyState({ icon: Icon, title, description, action }: { icon: typeof Package; title: string; description: string; action?: React.ReactNode }) {
  return <div className="flex min-h-[280px] flex-col items-center justify-center rounded-3xl border border-dashed border-[#cfe1dc] bg-[#fbfdfc] p-8 text-center"><span className="mb-4 grid h-14 w-14 place-items-center rounded-2xl bg-[#e3f3ee] text-[#0e716b]"><Icon size={25} /></span><h3 className="font-black text-[#173b3c]">{title}</h3><p className="mt-2 max-w-sm text-sm leading-6 text-slate-500">{description}</p>{action && <div className="mt-5">{action}</div>}</div>;
}

function StatCard({ label, value, detail, icon: Icon, tone = "teal", compact = false }: { label: string; value: string; detail?: string; icon: typeof Wallet; tone?: "teal" | "orange" | "blue" | "rose"; compact?: boolean }) {
  const tones = { teal: "bg-[#e2f4ef] text-[#0e716b]", orange: "bg-[#fff0e3] text-[#ae5d28]", blue: "bg-[#e9efff] text-[#496bc0]", rose: "bg-[#ffebed] text-[#be5562]" };
  return <Card className={`border-[#e2ece9] shadow-[0_8px_30px_rgba(20,70,67,.045)] ${compact ? "min-w-[180px]" : ""}`}><CardContent className="flex items-start justify-between p-5"><div><p className="text-xs font-bold uppercase tracking-[.1em] text-slate-400">{label}</p><p className="mt-2 text-2xl font-black tracking-tight text-[#173b3c]">{value}</p>{detail && <p className="mt-2 text-xs font-semibold text-slate-500">{detail}</p>}</div><span className={`grid h-10 w-10 place-items-center rounded-xl ${tones[tone]}`}><Icon size={19} /></span></CardContent></Card>;
}

function StatusBadge({ status }: { status: string }) {
  const style = status === "completed" || status === "paid" || status === "approved" ? "border-[#bde4d7] bg-[#e8f8f2] text-[#14745f]" : status === "cancelled" ? "border-[#f3c7cc] bg-[#fff0f1] text-[#ad4c59]" : "border-[#f2d2a4] bg-[#fff7e8] text-[#a66b1c]";
  return <Badge variant="outline" className={`rounded-full px-2.5 py-1 text-[10px] font-extrabold uppercase tracking-wide ${style}`}>{statusLabels[status] || status}</Badge>;
}

export default function Index() {
  const { session, loading: sessionLoading } = useSession();
  const navigate = useNavigate();
  const location = useLocation();
  const [company, setCompany] = useState<Company | null>(null);
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [finance, setFinance] = useState<Finance[]>([]);
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [categories, setCategories] = useState<{ id: string; name: string }[]>([]);
  const [dataLoading, setDataLoading] = useState(true);
  const [mobileNav, setMobileNav] = useState(false);
  const [profileName, setProfileName] = useState("");
  const [membershipRole, setMembershipRole] = useState<"admin" | "employee">("admin");

  const ensureWorkspace = useCallback(async () => {
    if (!session?.user) return;
    setDataLoading(true);
    const { data: membership } = await localApi.from("company_members").select("company_id, role, companies(*)").eq("user_id", session.user.id).limit(1).maybeSingle();
    if (membership?.companies) {
      setMembershipRole(membership.role as "admin" | "employee");
      setCompany(membership.companies as unknown as Company);
    } else {
      const { data: created, error } = await localApi.rpc("create_company_workspace", { company_name: "Minha empresa" });
      if (error || !created) {
        toast.error("Não foi possível preparar o espaço da empresa.");
        setDataLoading(false);
        return;
      }
      setMembershipRole("admin");
      setCompany(created as Company);
    }
    const { data: profile } = await localApi.from("profiles").select("full_name").eq("id", session.user.id).maybeSingle();
    setProfileName(profile?.full_name || session.user.email?.split("@")[0] || "Operador");
  }, [session]);

  const refreshData = useCallback(async () => {
    if (!company) return;
    setDataLoading(true);
    const productQuery = membershipRole === "admin"
      ? localApi.from("admin_products").select("*").eq("company_id", company.id).order("name")
      : localApi.from("products").select("id, company_id, category_id, name, barcode, sku, description, image_url, sale_price, stock, minimum_stock, supplier_name, is_active, updated_at").eq("company_id", company.id).order("name");
    const [productsRes, customersRes, salesRes, financeRes, quotesRes, categoriesRes] = await Promise.all([
      productQuery,
      localApi.from("customers").select("*").eq("company_id", company.id).order("name"),
      localApi.from("sales").select("id, sale_number, customer_id, status, payment_method, total, created_at, customers(name)").eq("company_id", company.id).order("created_at", { ascending: false }),
      localApi.from("financial_transactions").select("*").eq("company_id", company.id).order("occurred_at", { ascending: false }),
      localApi.from("quotes").select("id, quote_number, customer_id, status, subtotal, discount, total, notes, created_at, customers(name)").eq("company_id", company.id).order("created_at", { ascending: false }).limit(100),
      localApi.from("categories").select("id, name").eq("company_id", company.id).order("name"),
    ]);
    setProducts((productsRes.data || []).map((product) => ({ ...product, cost_price: product.cost_price || 0 })) as Product[]);
    setCustomers((customersRes.data || []) as Customer[]);
    setSales((salesRes.data || []).map((row) => ({ ...row, customers: Array.isArray(row.customers) ? row.customers[0] || null : row.customers })) as Sale[]);
    setFinance((financeRes.data || []) as Finance[]);
    setQuotes((quotesRes.data || []).map((row) => ({ ...row, customers: Array.isArray(row.customers) ? row.customers[0] || null : row.customers })) as Quote[]);
    setCategories((categoriesRes.data || []) as { id: string; name: string }[]);
    setDataLoading(false);
  }, [company, membershipRole]);

  useEffect(() => { if (!sessionLoading && !session) navigate("/login", { replace: true }); }, [session, sessionLoading, navigate]);
  useEffect(() => { if (session) void ensureWorkspace(); }, [session, ensureWorkspace]);
  useEffect(() => { if (company) void refreshData(); }, [company, refreshData]);
  const currentKey = location.pathname.startsWith("/vendas") ? "sale" : location.pathname.startsWith("/produtos") ? "products" : location.pathname.startsWith("/clientes") ? "customers" : location.pathname.startsWith("/financeiro") ? "finance" : location.pathname.startsWith("/orcamentos") ? "quotes" : location.pathname.startsWith("/relatorios") ? "reports" : location.pathname.startsWith("/configuracoes") ? "settings" : "dashboard";
  useEffect(() => { if (membershipRole === "employee" && ["customers", "finance", "quotes", "reports", "settings"].includes(currentKey)) navigate("/", { replace: true }); }, [membershipRole, currentKey, navigate]);

  if (sessionLoading || (session && !company && dataLoading)) return <div className="grid min-h-screen place-items-center bg-[#f5faf8]"><div className="flex items-center gap-3 text-sm font-bold text-[#0e716b]"><span className="grid h-10 w-10 animate-pulse place-items-center rounded-2xl bg-[#dff2ed]"><PackageCheck size={20} /></span>Preparando seu espaço...</div></div>;
  if (!session) return null;
  const isAdmin = membershipRole === "admin";
  const allowedNavItems = navItems.filter((item) => isAdmin || !["customers", "finance", "quotes", "reports", "settings"].includes(item.key));
  const currentLabel = navItems.find((item) => item.key === currentKey)?.label || "Dashboard";
  const go = (path: string) => { navigate(path); setMobileNav(false); };

  return <div className="min-h-screen bg-[#f5faf8] text-[#173b3c]">
    <aside className="fixed inset-y-0 left-0 z-30 hidden w-[254px] flex-col bg-[#0e4f50] px-4 py-5 text-white lg:flex">
      <div className="flex items-center gap-3 px-3"><span className="grid h-10 w-10 place-items-center rounded-2xl bg-[#f5a56b] text-[#0e4f50]"><PackageCheck size={22} /></span><span className="text-lg font-black tracking-tight">ControlaVenda</span></div>
      <div className="mt-10 px-3 text-[10px] font-bold uppercase tracking-[.2em] text-[#8dcfc1]">Operação</div>
      <nav className="mt-3 flex-1 space-y-1">{allowedNavItems.map((item) => <NavItem key={item.key} item={item} active={currentKey === item.key} onClick={() => go(item.path)} />)}</nav>
      <div className="rounded-2xl border border-white/10 bg-white/5 p-3"><div className="flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-xl bg-[#2a7c75] text-xs font-black">{initials(profileName || "CV")}</span><div className="min-w-0"><p className="truncate text-sm font-bold">{profileName || "Operador"}</p><p className="text-[11px] text-[#a8dfd1]">{isAdmin ? "Administrador" : "Funcionário"}</p></div><button onClick={() => localApi.auth.signOut()} className="ml-auto text-[#a8dfd1] transition hover:text-white" title="Sair"><LogOut size={16} /></button></div></div>
    </aside>
    {mobileNav && <div className="fixed inset-0 z-40 bg-[#082e30]/40 lg:hidden" onClick={() => setMobileNav(false)}><aside className="h-full w-[285px] bg-[#0e4f50] px-4 py-5 text-white" onClick={(event) => event.stopPropagation()}><div className="flex items-center justify-between px-3"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-2xl bg-[#f5a56b] text-[#0e4f50]"><PackageCheck size={22} /></span><span className="text-lg font-black">ControlaVenda</span></div><button onClick={() => setMobileNav(false)}><X size={20} /></button></div><nav className="mt-10 space-y-1">{allowedNavItems.map((item) => <NavItem key={item.key} item={item} active={currentKey === item.key} onClick={() => go(item.path)} />)}</nav></aside></div>}
    <div className="lg:pl-[254px]"><header className="sticky top-0 z-20 flex h-[76px] items-center justify-between border-b border-[#e2ece9] bg-[#f5faf8]/90 px-5 backdrop-blur-xl sm:px-8"><div className="flex items-center gap-3"><button className="rounded-xl p-2 text-[#0e716b] hover:bg-[#e3f3ee] lg:hidden" onClick={() => setMobileNav(true)}><Menu size={22} /></button><div><p className="hidden text-xs font-semibold text-slate-400 sm:block">Visão geral da operação</p><h1 className="text-xl font-black tracking-tight sm:text-2xl">{currentLabel}</h1></div></div><div className="flex items-center gap-2 sm:gap-4"><button className="relative grid h-10 w-10 place-items-center rounded-xl border border-[#dceae6] bg-white text-slate-500 transition hover:border-[#abd8cf] hover:text-[#0e716b]"><Bell size={18} /><span className="absolute right-2 top-2 h-1.5 w-1.5 rounded-full bg-[#f28b62]" /></button><div className="hidden items-center gap-2 border-l border-[#dceae6] pl-4 sm:flex"><span className="grid h-9 w-9 place-items-center rounded-xl bg-[#dff2ed] text-xs font-black text-[#0e716b]">{initials(profileName || "CV")}</span><div><p className="text-xs font-bold text-[#173b3c]">{profileName || "Operador"}</p><p className="text-[10px] text-slate-400">{company?.name || "Sua empresa"}</p></div></div></div></header><main className="mx-auto max-w-[1500px] p-5 sm:p-8">{company && <>{currentKey === "dashboard" && <Dashboard company={company} products={products} sales={sales} finance={finance} customers={customers} onNavigate={go} />}{currentKey === "sale" && <SaleView company={company} products={products} customers={customers} onSaved={refreshData} navigate={go} isAdmin={isAdmin} />}{currentKey === "products" && <ProductsView company={company} products={products} categories={categories} onSaved={refreshData} isAdmin={isAdmin} />}{currentKey === "customers" && isAdmin && <CustomersView company={company} customers={customers} onSaved={refreshData} />}{currentKey === "finance" && isAdmin && <FinanceView company={company} finance={finance} onSaved={refreshData} />}{currentKey === "quotes" && isAdmin && <QuotesView company={company} quotes={quotes} customers={customers} products={products} onSaved={refreshData} onConvert={go} />}{currentKey === "reports" && isAdmin && <ReportsView company={company} products={products} sales={sales} finance={finance} customers={customers} />}{currentKey === "settings" && isAdmin && <SettingsView company={company} onSaved={(next) => { setCompany(next); toast.success("Configurações salvas."); }} />}</>}</main></div>
  </div>;
}

function NavItem({ item, active, onClick }: { item: typeof navItems[number]; active: boolean; onClick: () => void }) { const Icon = item.icon; return <button onClick={onClick} className={`group flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm font-semibold transition ${active ? "bg-[#2a7c75] text-white shadow-[0_8px_20px_rgba(4,28,30,.15)]" : "text-[#b8dfd6] hover:bg-white/10 hover:text-white"}`}><Icon size={18} className={active ? "text-[#f5c299]" : "text-[#77bdb0] group-hover:text-[#b8dfd6]"} /><span>{item.label}</span>{active && <ChevronRight size={15} className="ml-auto text-[#f5c299]" />}</button>; }

function PageIntro({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: React.ReactNode }) { return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div>{eyebrow && <p className="mb-2 text-xs font-bold uppercase tracking-[.16em] text-[#0e716b]">{eyebrow}</p>}<h2 className="text-2xl font-black tracking-tight text-[#173b3c] sm:text-3xl">{title}</h2>{description && <p className="mt-2 max-w-2xl text-sm leading-6 text-slate-500">{description}</p>}</div>{action}</div>; }

function Dashboard({ company, products, sales, finance, customers, onNavigate }: { company: Company; products: Product[]; sales: Sale[]; finance: Finance[]; customers: Customer[]; onNavigate: (path: string) => void }) {
  const completedSales = sales.filter((sale) => sale.status !== "cancelled");
  const revenue = completedSales.reduce((sum, sale) => sum + asNumber(sale.total), 0);
  const income = finance.filter((item) => item.type === "income" && item.status !== "cancelled").reduce((sum, item) => sum + asNumber(item.amount), 0);
  const expenses = finance.filter((item) => item.type === "expense" && item.status !== "cancelled").reduce((sum, item) => sum + asNumber(item.amount), 0);
  const lowStock = products.filter((product) => product.stock > 0 && product.stock <= product.minimum_stock).length;
  const outOfStock = products.filter((product) => product.stock <= 0).length;
  const chartData = useMemo(() => { const days = Array.from({ length: 7 }, (_, index) => { const day = new Date(); day.setHours(0, 0, 0, 0); day.setDate(day.getDate() - (6 - index)); return day; }); return days.map((day) => ({ label: new Intl.DateTimeFormat("pt-BR", { weekday: "short" }).format(day).replace(".", ""), value: completedSales.filter((sale) => { const created = new Date(sale.created_at); return created.toDateString() === day.toDateString(); }).reduce((sum, sale) => sum + asNumber(sale.total), 0) })); }, [completedSales]);
  return <><PageIntro eyebrow="Bom dia, {name}" title={`Olá, ${company.name}`} description="Aqui está um resumo vivo da sua operação. Os indicadores são atualizados a partir das movimentações salvas." action={<Button onClick={() => onNavigate("/vendas/nova")} className="h-11 rounded-xl bg-[#0e716b] px-5 font-bold shadow-[0_8px_18px_rgba(14,113,107,.2)] hover:bg-[#0e4f50]"><Plus size={18} className="mr-2" /> Nova venda</Button>} /><div className="mb-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Receita registrada" value={money(revenue)} detail={`${completedSales.length} venda(s) no histórico`} icon={CircleDollarSign} /><StatCard label="Resultado financeiro" value={money(income - expenses)} detail={`${money(income)} em entradas`} icon={TrendingUp} tone="blue" /><StatCard label="Estoque baixo" value={String(lowStock)} detail={`${outOfStock} sem estoque`} icon={Boxes} tone="orange" /><StatCard label="Clientes" value={String(customers.length)} detail="cadastros ativos e inativos" icon={Users} tone="rose" /></div><div className="grid gap-6 xl:grid-cols-[1.45fr_.8fr]"><Card className="border-[#e2ece9] shadow-[0_8px_30px_rgba(20,70,67,.045)]"><CardHeader className="flex-row items-start justify-between space-y-0 pb-2"><div><CardTitle className="text-base font-black">Movimento de vendas</CardTitle><p className="mt-1 text-xs text-slate-400">Últimos 7 dias</p></div><Badge variant="outline" className="rounded-full border-[#c5e4dc] bg-[#effaf6] text-[#0e716b]">Dados reais</Badge></CardHeader><CardContent><div className="h-[260px] w-full"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chartData} margin={{ top: 16, right: 8, left: -22, bottom: 0 }}><defs><linearGradient id="salesFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#3da998" stopOpacity={0.28} /><stop offset="100%" stopColor="#3da998" stopOpacity={0.02} /></linearGradient></defs><CartesianGrid stroke="#e8f0ed" vertical={false} /><XAxis dataKey="label" axisLine={false} tickLine={false} tick={{ fill: "#8a9c99", fontSize: 11 }} /><Tooltip formatter={(value: number) => [money(value), "Vendas"]} contentStyle={{ borderRadius: 14, border: "1px solid #dceae6", boxShadow: "0 12px 30px rgba(20,70,67,.1)" }} /><Area type="monotone" dataKey="value" stroke="#0e716b" strokeWidth={3} fill="url(#salesFill)" /></AreaChart></ResponsiveContainer></div></CardContent></Card><Card className="border-[#e2ece9] shadow-[0_8px_30px_rgba(20,70,67,.045)]"><CardHeader className="flex-row items-center justify-between space-y-0"><div><CardTitle className="text-base font-black">Atenção necessária</CardTitle><p className="mt-1 text-xs text-slate-400">Alertas da operação</p></div><Bell size={18} className="text-[#f28b62]" /></CardHeader><CardContent className="space-y-3">{lowStock > 0 && <AlertRow icon={Boxes} title={`${lowStock} produto(s) com estoque baixo`} description="Reveja os níveis mínimos cadastrados." tone="orange" onClick={() => onNavigate("/produtos")} />}{outOfStock > 0 && <AlertRow icon={Archive} title={`${outOfStock} produto(s) sem estoque`} description="Evite perder vendas por falta de reposição." tone="rose" onClick={() => onNavigate("/produtos")} />}{sales.filter((sale) => sale.status === "pending").length > 0 && <AlertRow icon={Wallet} title="Existem vendas pendentes" description="Confira os recebimentos em aberto." tone="blue" onClick={() => onNavigate("/financeiro")} />}{lowStock === 0 && outOfStock === 0 && sales.filter((sale) => sale.status === "pending").length === 0 && <div className="flex flex-col items-center py-8 text-center"><span className="grid h-12 w-12 place-items-center rounded-full bg-[#e7f7f1] text-[#0e716b]"><Check size={22} /></span><p className="mt-3 text-sm font-bold">Tudo sob controle</p><p className="mt-1 text-xs text-slate-400">Nenhum alerta relevante agora.</p></div>}</CardContent></Card></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.25fr_.75fr]"><Card className="border-[#e2ece9] shadow-[0_8px_30px_rgba(20,70,67,.045)]"><CardHeader className="flex-row items-center justify-between space-y-0"><div><CardTitle className="text-base font-black">Últimas vendas</CardTitle><p className="mt-1 text-xs text-slate-400">Histórico mais recente</p></div><Button variant="ghost" onClick={() => onNavigate("/relatorios")} className="text-xs font-bold text-[#0e716b] hover:bg-[#eff8f5]">Ver relatório <ChevronRight size={15} /></Button></CardHeader><CardContent className="p-0"><div className="overflow-x-auto"><Table><TableHeader><TableRow className="border-[#edf2f0] hover:bg-transparent"><TableHead className="pl-6 text-[10px] uppercase tracking-wider text-slate-400">Venda</TableHead><TableHead className="text-[10px] uppercase tracking-wider text-slate-400">Cliente</TableHead><TableHead className="text-[10px] uppercase tracking-wider text-slate-400">Data</TableHead><TableHead className="text-[10px] uppercase tracking-wider text-slate-400">Pagamento</TableHead><TableHead className="pr-6 text-right text-[10px] uppercase tracking-wider text-slate-400">Total</TableHead></TableRow></TableHeader><TableBody>{sales.slice(0, 5).map((sale) => <TableRow key={sale.id} className="border-[#edf2f0]"><TableCell className="pl-6 font-bold text-[#0e716b]">#{sale.sale_number}</TableCell><TableCell className="font-semibold text-[#173b3c]">{sale.customers?.name || "Consumidor final"}</TableCell><TableCell className="text-xs text-slate-500">{dateTime(sale.created_at)}</TableCell><TableCell><span className="text-xs font-semibold text-slate-600">{paymentLabels[sale.payment_method] || sale.payment_method}</span></TableCell><TableCell className="pr-6 text-right font-black">{money(sale.total)}</TableCell></TableRow>)}{sales.length === 0 && <TableRow><TableCell colSpan={5} className="py-14 text-center text-sm text-slate-400">As vendas registradas aparecerão aqui.</TableCell></TableRow>}</TableBody></Table></div></CardContent></Card><Card className="border-[#e2ece9] bg-[#0e4f50] text-white shadow-[0_8px_30px_rgba(20,70,67,.1)]"><CardContent className="relative overflow-hidden p-6"><div className="absolute -right-8 -top-12 h-36 w-36 rounded-full border-[22px] border-[#f5a56b]/25" /><Sparkles className="mb-6 text-[#f5a56b]" size={22} /><p className="text-xs font-bold uppercase tracking-[.15em] text-[#9ed8cb]">Resumo financeiro</p><p className="mt-2 text-3xl font-black">{money(income - expenses)}</p><p className="mt-2 text-sm text-[#b9e1d8]">resultado com base nos lançamentos salvos</p><div className="mt-8 grid grid-cols-2 gap-3"><div className="rounded-2xl bg-white/10 p-3"><ArrowUpRight size={16} className="mb-2 text-[#92e1c2]" /><p className="text-xs text-[#b9e1d8]">Entradas</p><p className="mt-1 text-sm font-black">{money(income)}</p></div><div className="rounded-2xl bg-white/10 p-3"><ArrowDownRight size={16} className="mb-2 text-[#f5a56b]" /><p className="text-xs text-[#b9e1d8]">Saídas</p><p className="mt-1 text-sm font-black">{money(expenses)}</p></div></div></CardContent></Card></div></>;
}

function AlertRow({ icon: Icon, title, description, tone, onClick }: { icon: typeof Boxes; title: string; description: string; tone: "orange" | "rose" | "blue"; onClick: () => void }) { const colors = { orange: "bg-[#fff0e3] text-[#ae5d28]", rose: "bg-[#ffebed] text-[#be5562]", blue: "bg-[#e9efff] text-[#496bc0]" }; return <button onClick={onClick} className="flex w-full items-center gap-3 rounded-2xl border border-[#edf2f0] p-3 text-left transition hover:border-[#c8dfd9] hover:bg-[#fbfdfc]"><span className={`grid h-9 w-9 shrink-0 place-items-center rounded-xl ${colors[tone]}`}><Icon size={17} /></span><span className="min-w-0 flex-1"><span className="block text-sm font-bold text-[#173b3c]">{title}</span><span className="mt-0.5 block text-xs text-slate-400">{description}</span></span><ChevronRight size={15} className="text-slate-300" /></button>; }

function ProductsView({ company, products, categories, onSaved, isAdmin }: { company: Company; products: Product[]; categories: { id: string; name: string }[]; onSaved: () => Promise<void>; isAdmin: boolean }) {
  const [search, setSearch] = useState(""); const [filter, setFilter] = useState("all"); const [open, setOpen] = useState(false); const [editing, setEditing] = useState<Product | null>(null); const [form, setForm] = useState({ name: "", barcode: "", sku: "", category_id: "", cost_price: "", sale_price: "", stock: "", minimum_stock: "", supplier_name: "", description: "" });
  const filtered = products.filter((product) => { const term = search.toLowerCase(); const matches = !term || [product.name, product.barcode, product.sku].some((value) => value?.toLowerCase().includes(term)); const filterMatch = filter === "all" || (filter === "active" && product.is_active) || (filter === "inactive" && !product.is_active) || (filter === "low" && product.stock > 0 && product.stock <= product.minimum_stock) || (filter === "empty" && product.stock <= 0); return matches && filterMatch; });
  const openForm = (product?: Product) => { setEditing(product || null); setForm(product ? { name: product.name, barcode: product.barcode || "", sku: product.sku || "", category_id: product.category_id || "", cost_price: String(product.cost_price), sale_price: String(product.sale_price), stock: String(product.stock), minimum_stock: String(product.minimum_stock), supplier_name: product.supplier_name || "", description: product.description || "" } : { name: "", barcode: "", sku: "", category_id: "", cost_price: "", sale_price: "", stock: "", minimum_stock: "", supplier_name: "", description: "" }); setOpen(true); };
  const save = async (event: React.FormEvent) => { event.preventDefault(); if (!form.name.trim()) return toast.error("Informe o nome do produto."); const payload = { company_id: company.id, name: form.name.trim(), barcode: form.barcode.trim() || null, sku: form.sku.trim() || null, category_id: form.category_id || null, cost_price: Math.max(0, asNumber(form.cost_price)), sale_price: Math.max(0, asNumber(form.sale_price)), stock: Math.max(0, asNumber(form.stock)), minimum_stock: Math.max(0, asNumber(form.minimum_stock)), supplier_name: form.supplier_name.trim() || null, description: form.description.trim() || null, is_active: editing?.is_active ?? true, updated_at: new Date().toISOString() }; const result = editing ? await localApi.from("products").update(payload).eq("id", editing.id).select("id").single() : await localApi.from("products").insert(payload).select("id").single(); if (result.error) return toast.error(result.error.code === "23505" ? "Este código de barras já está cadastrado." : "Não foi possível salvar o produto."); setOpen(false); toast.success(editing ? "Produto atualizado com sucesso." : "Produto cadastrado com sucesso."); await onSaved(); };
  const toggle = async (product: Product) => { const next = !product.is_active; const { error } = await localApi.from("products").update({ is_active: next, updated_at: new Date().toISOString() }).eq("id", product.id); if (error) toast.error("Não foi possível atualizar o status."); else { toast.success(next ? "Produto ativado." : "Produto desativado."); await onSaved(); } };
  return <><PageIntro eyebrow="Catálogo central" title="Produtos" description="Cadastre preços, códigos e níveis de estoque. Produtos inativos permanecem no histórico." action={isAdmin ? <Button onClick={() => openForm()} className="h-11 rounded-xl bg-[#0e716b] font-bold hover:bg-[#0e4f50]"><Plus size={18} className="mr-2" /> Novo produto</Button> : undefined} /><Card className="border-[#e2ece9] shadow-[0_8px_30px_rgba(20,70,67,.045)]"><CardContent className="p-4 sm:p-6"><div className="mb-5 flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"><div className="relative max-w-md flex-1"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={17} /><Input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Buscar por nome, código ou SKU" className="h-11 rounded-xl border-[#dceae6] pl-10" /></div><div className="flex items-center gap-2 overflow-x-auto pb-1"><SlidersHorizontal size={16} className="shrink-0 text-slate-400" />{[["all", "Todos"], ["active", "Ativos"], ["low", "Estoque baixo"], ["empty", "Sem estoque"], ["inactive", "Inativos"]].map(([key, label]) => <button key={key} onClick={() => setFilter(key)} className={`whitespace-nowrap rounded-full px-3 py-2 text-xs font-bold transition ${filter === key ? "bg-[#0e716b] text-white" : "bg-[#f2f7f5] text-slate-500 hover:bg-[#e5f1ed]"}`}>{label}</button>)}</div></div>{filtered.length === 0 ? <EmptyState icon={Package} title="Nenhum produto encontrado" description="Ajuste sua busca ou cadastre o primeiro produto da empresa." action={isAdmin ? <Button onClick={() => openForm()} className="rounded-xl bg-[#0e716b] hover:bg-[#0e4f50]"><Plus size={16} className="mr-2" /> Cadastrar produto</Button> : undefined} /> : <div className="overflow-x-auto"><Table><TableHeader><TableRow className="border-[#edf2f0] hover:bg-transparent"><TableHead className="pl-2 text-[10px] uppercase tracking-wider text-slate-400">Produto</TableHead><TableHead className="text-[10px] uppercase tracking-wider text-slate-400">Código</TableHead><TableHead className="text-[10px] uppercase tracking-wider text-slate-400">Preço / margem</TableHead><TableHead className="text-[10px] uppercase tracking-wider text-slate-400">Estoque</TableHead><TableHead className="text-[10px] uppercase tracking-wider text-slate-400">Status</TableHead><TableHead /></TableRow></TableHeader><TableBody>{filtered.map((product) => { const margin = product.sale_price ? (product.sale_price - product.cost_price) / product.sale_price * 100 : 0; const stockTone = product.stock <= 0 ? "text-[#be5562]" : product.stock <= product.minimum_stock ? "text-[#ae5d28]" : "text-[#14745f]"; return <TableRow key={product.id} className="border-[#edf2f0]"><TableCell className="pl-2"><div><p className="font-bold text-[#173b3c]">{product.name}</p><p className="mt-1 text-xs text-slate-400">{categories.find((category) => category.id === product.category_id)?.name || "Sem categoria"}</p></div></TableCell><TableCell className="font-mono text-xs text-slate-500">{product.barcode || product.sku || "—"}</TableCell><TableCell><p className="font-bold">{money(product.sale_price)}</p>{isAdmin && <p className="text-xs text-[#0e716b]">{percent(margin)} margem</p>}</TableCell><TableCell><span className={`font-black ${stockTone}`}>{product.stock}</span><span className="ml-1 text-xs text-slate-400">/ mín. {product.minimum_stock}</span></TableCell><TableCell>{isAdmin ? <button onClick={() => toggle(product)}><StatusBadge status={product.is_active ? "approved" : "cancelled"} /></button> : <StatusBadge status={product.is_active ? "approved" : "cancelled"} />}</TableCell><TableCell className="text-right">{isAdmin && <Button variant="ghost" size="icon" onClick={() => openForm(product)} className="rounded-xl text-slate-400 hover:bg-[#eff8f5] hover:text-[#0e716b]"><Pencil size={16} /></Button>}</TableCell></TableRow>; })}</TableBody></Table></div>}</CardContent></Card><Dialog open={open} onOpenChange={setOpen}><DialogContent className="max-w-2xl rounded-3xl border-[#dceae6]"><DialogHeader><DialogTitle className="text-xl font-black">{editing ? "Editar produto" : "Novo produto"}</DialogTitle><DialogDescription>O cadastro é a fonte oficial usada no estoque e nas vendas.</DialogDescription></DialogHeader><form onSubmit={save} className="grid max-h-[70vh] gap-4 overflow-y-auto py-2 sm:grid-cols-2"><Field label="Nome do produto" required><Input value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} placeholder="Ex.: Arroz 5kg" /></Field><Field label="Código de barras"><Input value={form.barcode} onChange={(event) => setForm({ ...form, barcode: event.target.value })} placeholder="789..." /></Field><Field label="SKU / código interno"><Input value={form.sku} onChange={(event) => setForm({ ...form, sku: event.target.value })} /></Field><Field label="Categoria"><select value={form.category_id} onChange={(event) => setForm({ ...form, category_id: event.target.value })} className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="">Sem categoria</option>{categories.map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></Field><Field label="Preço de custo"><Input type="number" min="0" step="0.01" value={form.cost_price} onChange={(event) => setForm({ ...form, cost_price: event.target.value })} /></Field><Field label="Preço de venda"><Input type="number" min="0" step="0.01" value={form.sale_price} onChange={(event) => setForm({ ...form, sale_price: event.target.value })} /></Field><Field label="Estoque atual"><Input type="number" min="0" step="0.001" value={form.stock} onChange={(event) => setForm({ ...form, stock: event.target.value })} /></Field><Field label="Estoque mínimo"><Input type="number" min="0" step="0.001" value={form.minimum_stock} onChange={(event) => setForm({ ...form, minimum_stock: event.target.value })} /></Field><Field label="Fornecedor"><Input value={form.supplier_name} onChange={(event) => setForm({ ...form, supplier_name: event.target.value })} /></Field><div className="sm:col-span-2"><Field label="Descrição"><Textarea value={form.description} onChange={(event) => setForm({ ...form, description: event.target.value })} className="min-h-20" /></Field></div><DialogFooter className="sm:col-span-2"><Button type="button" variant="ghost" onClick={() => setOpen(false)} className="rounded-xl">Cancelar</Button><Button type="submit" className="rounded-xl bg-[#0e716b] font-bold hover:bg-[#0e4f50]">Salvar produto</Button></DialogFooter></form></DialogContent></Dialog></>;
}

function Field({ label, required, children }: { label: string; required?: boolean; children: React.ReactNode }) { return <div className="space-y-1.5"><Label className="text-xs font-bold text-slate-600">{label}{required && <span className="ml-1 text-[#f28b62]">*</span>}</Label>{children}</div>; }

function NewCustomerDialog({ company, open, onOpenChange, onCreated }: { company: Company; open: boolean; onOpenChange: (open: boolean) => void; onCreated: (customer: Customer) => Promise<void> }) {
  const [form, setForm] = useState({ name: "", phone: "", whatsapp: "", email: "", tax_id: "" });
  const [saving, setSaving] = useState(false);
  const save = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!form.name.trim()) return toast.error("Informe o nome do cliente.");
    setSaving(true);
    const { data, error } = await localApi.rpc("create_customer", {
      target_company: company.id,
      customer_name: form.name,
      customer_phone: form.phone,
      customer_whatsapp: form.whatsapp,
      customer_email: form.email,
      customer_tax_id: form.tax_id,
    });
    setSaving(false);
    if (error || !data) return toast.error(error?.message || "Não foi possível cadastrar o cliente.");
    setForm({ name: "", phone: "", whatsapp: "", email: "", tax_id: "" });
    onOpenChange(false);
    await onCreated(data as Customer);
    toast.success("Cliente cadastrado e selecionado para a venda.");
  };
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="rounded-3xl border-[#dceae6]"><DialogHeader><DialogTitle className="font-black">Novo cliente</DialogTitle><DialogDescription>O cadastro será salvo automaticamente na aba Clientes.</DialogDescription></DialogHeader><form onSubmit={save} className="grid gap-4 sm:grid-cols-2"><div className="sm:col-span-2"><Field label="Nome" required><Input autoFocus value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} /></Field></div><Field label="Telefone"><Input value={form.phone} onChange={(event) => setForm({ ...form, phone: event.target.value })} /></Field><Field label="WhatsApp"><Input value={form.whatsapp} onChange={(event) => setForm({ ...form, whatsapp: event.target.value })} /></Field><Field label="E-mail"><Input type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} /></Field><Field label="CPF / CNPJ"><Input value={form.tax_id} onChange={(event) => setForm({ ...form, tax_id: event.target.value })} /></Field><DialogFooter className="sm:col-span-2"><Button type="button" variant="ghost" onClick={() => onOpenChange(false)} className="rounded-xl">Cancelar</Button><Button disabled={saving} type="submit" className="rounded-xl bg-[#0e716b] hover:bg-[#0e4f50]">{saving ? "Salvando..." : "Cadastrar cliente"}</Button></DialogFooter></form></DialogContent></Dialog>;
}

function CustomersView({ company, customers, onSaved }: { company: Company; customers: Customer[]; onSaved: () => Promise<void> }) { const [search, setSearch] = useState(""); const [open, setOpen] = useState(false); const [editing, setEditing] = useState<Customer | null>(null); const empty = { name: "", phone: "", whatsapp: "", email: "", address: "", address_number: "", city: "", state: "", tax_id: "", notes: "" }; const [form, setForm] = useState(empty); const filtered = customers.filter((customer) => `${customer.name} ${customer.email || ""} ${customer.phone || ""} ${customer.tax_id || ""}`.toLowerCase().includes(search.toLowerCase())); const edit = (customer?: Customer) => { setEditing(customer || null); setForm(customer ? { name: customer.name, phone: customer.phone || "", whatsapp: customer.whatsapp || "", email: customer.email || "", address: customer.address || "", address_number: customer.address_number || "", city: customer.city || "", state: customer.state || "", tax_id: customer.tax_id || "", notes: customer.notes || "" } : empty); setOpen(true); }; const save = async (event: React.FormEvent) => { event.preventDefault(); if (!form.name.trim()) return toast.error("Informe o nome do cliente."); const payload = { ...form, company_id: company.id, updated_at: new Date().toISOString(), is_active: editing?.is_active ?? true }; const result = editing ? await localApi.from("customers").update(payload).eq("id", editing.id) : await localApi.from("customers").insert(payload); if (result.error) return toast.error("Não foi possível salvar o cliente."); setOpen(false); toast.success(editing ? "Cliente atualizado." : "Cliente cadastrado."); await onSaved(); }; const toggle = async (customer: Customer) => { await localApi.from("customers").update({ is_active: !customer.is_active }).eq("id", customer.id); toast.success(customer.is_active ? "Cliente desativado." : "Cliente ativado."); await onSaved(); }; return <><PageIntro eyebrow="Relacionamento" title="Clientes" description="Centralize contatos, histórico de compras e informações para vendas e orçamentos." action={<Button onClick={() => edit()} className="h-11 rounded-xl bg-[#0e716b] font-bold hover:bg-[#0e4f50]"><Plus size={18} className="mr-2" /> Novo cliente</Button>} /><Card className="border-[#e2ece9] shadow-[0_8px_30px_rgba(20,70,67,.045)]"><CardContent className="p-4 sm:p-6"><div className="relative mb-5 max-w-md"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={17} /><Input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Buscar cliente, telefone ou CPF/CNPJ" className="h-11 rounded-xl border-[#dceae6] pl-10" /></div>{filtered.length === 0 ? <EmptyState icon={Users} title="Nenhum cliente encontrado" description="Cadastre clientes para vincular às vendas e gerar orçamentos personalizados." action={<Button onClick={() => edit()} className="rounded-xl bg-[#0e716b] hover:bg-[#0e4f50]"><Plus size={16} className="mr-2" /> Cadastrar cliente</Button>} /> : <div className="overflow-x-auto"><Table><TableHeader><TableRow className="border-[#edf2f0] hover:bg-transparent"><TableHead className="pl-2 text-[10px] uppercase tracking-wider text-slate-400">Cliente</TableHead><TableHead className="text-[10px] uppercase tracking-wider text-slate-400">Contato</TableHead><TableHead className="text-[10px] uppercase tracking-wider text-slate-400">Documento</TableHead><TableHead className="text-[10px] uppercase tracking-wider text-slate-400">Cidade</TableHead><TableHead className="text-[10px] uppercase tracking-wider text-slate-400">Status</TableHead><TableHead /></TableRow></TableHeader><TableBody>{filtered.map((customer) => <TableRow key={customer.id} className="border-[#edf2f0]"><TableCell className="pl-2"><p className="font-bold">{customer.name}</p><p className="mt-1 text-xs text-slate-400">{customer.email || "Sem e-mail"}</p></TableCell><TableCell className="text-sm text-slate-600">{customer.whatsapp || customer.phone || "—"}</TableCell><TableCell className="text-sm text-slate-600">{customer.tax_id || "—"}</TableCell><TableCell className="text-sm text-slate-600">{customer.city ? `${customer.city}${customer.state ? ` / ${customer.state}` : ""}` : "—"}</TableCell><TableCell><button onClick={() => toggle(customer)}><StatusBadge status={customer.is_active ? "approved" : "cancelled"} /></button></TableCell><TableCell className="text-right"><Button variant="ghost" size="icon" onClick={() => edit(customer)} className="rounded-xl text-slate-400 hover:bg-[#eff8f5] hover:text-[#0e716b]"><Pencil size={16} /></Button></TableCell></TableRow>)}</TableBody></Table></div>}</CardContent></Card><Dialog open={open} onOpenChange={setOpen}><DialogContent className="max-w-2xl rounded-3xl border-[#dceae6]"><DialogHeader><DialogTitle className="text-xl font-black">{editing ? "Editar cliente" : "Novo cliente"}</DialogTitle><DialogDescription>O cadastro poderá ser usado no caixa e nos orçamentos.</DialogDescription></DialogHeader><form onSubmit={save} className="grid max-h-[70vh] gap-4 overflow-y-auto py-2 sm:grid-cols-2"><Field label="Nome" required><Input value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} /></Field><Field label="CPF / CNPJ"><Input value={form.tax_id} onChange={(event) => setForm({ ...form, tax_id: event.target.value })} /></Field><Field label="Telefone"><Input value={form.phone} onChange={(event) => setForm({ ...form, phone: event.target.value })} /></Field><Field label="WhatsApp"><Input value={form.whatsapp} onChange={(event) => setForm({ ...form, whatsapp: event.target.value })} /></Field><Field label="E-mail"><Input type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} /></Field><Field label="Endereço"><Input value={form.address} onChange={(event) => setForm({ ...form, address: event.target.value })} /></Field><Field label="Número"><Input value={form.address_number} onChange={(event) => setForm({ ...form, address_number: event.target.value })} /></Field><Field label="Cidade"><Input value={form.city} onChange={(event) => setForm({ ...form, city: event.target.value })} /></Field><Field label="Estado"><Input maxLength={2} value={form.state} onChange={(event) => setForm({ ...form, state: event.target.value.toUpperCase() })} /></Field><div className="sm:col-span-2"><Field label="Observações"><Textarea value={form.notes} onChange={(event) => setForm({ ...form, notes: event.target.value })} /></Field></div><DialogFooter className="sm:col-span-2"><Button type="button" variant="ghost" onClick={() => setOpen(false)} className="rounded-xl">Cancelar</Button><Button type="submit" className="rounded-xl bg-[#0e716b] hover:bg-[#0e4f50]">Salvar cliente</Button></DialogFooter></form></DialogContent></Dialog></>; }

function SaleView({ company, products, customers, onSaved, navigate, isAdmin }: { company: Company; products: Product[]; customers: Customer[]; onSaved: () => Promise<void>; navigate: (path: string) => void; isAdmin: boolean }) { const barcodeRef = useRef<HTMLInputElement>(null); const [barcode, setBarcode] = useState(""); const [search, setSearch] = useState(""); const [cart, setCart] = useState<CartItem[]>([]); const [customerId, setCustomerId] = useState(""); const [customerOptions, setCustomerOptions] = useState(customers); const [newCustomerOpen, setNewCustomerOpen] = useState(false); useEffect(() => setCustomerOptions(customers), [customers]); const [paymentMethod, setPaymentMethod] = useState("pix"); const [paymentStatus, setPaymentStatus] = useState("paid"); const [amountReceived, setAmountReceived] = useState(""); const [generalType, setGeneralType] = useState<"fixed" | "percent">("fixed"); const [generalDiscount, setGeneralDiscount] = useState(""); const [missingBarcode, setMissingBarcode] = useState(""); const [quickProduct, setQuickProduct] = useState(false); const [saving, setSaving] = useState(false); const [quickForm, setQuickForm] = useState({ name: "", sale_price: "", cost_price: "", stock: "", minimum_stock: "" }); const matching = products.filter((product) => product.is_active && `${product.name} ${product.barcode || ""} ${product.sku || ""}`.toLowerCase().includes(search.toLowerCase())).slice(0, 5); const subtotal = cart.reduce((sum, item) => sum + item.quantity * item.unitPrice, 0); const productDiscount = cart.reduce((sum, item) => sum + itemDiscount(item), 0); const grossAfterItems = Math.max(0, subtotal - productDiscount); const generalDiscountAmount = generalType === "percent" ? grossAfterItems * Math.min(100, Math.max(0, asNumber(generalDiscount))) / 100 : Math.min(grossAfterItems, Math.max(0, asNumber(generalDiscount))); const total = Math.max(0, grossAfterItems - generalDiscountAmount); const change = Math.max(0, asNumber(amountReceived) - total); const addProduct = (product: Product) => { setCart((current) => { const existing = current.find((item) => item.productId === product.id); if (existing) return current.map((item) => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item); return [...current, { productId: product.id, name: product.name, barcode: product.barcode, costPrice: product.cost_price, quantity: 1, unitPrice: product.sale_price, discountType: "fixed", discountValue: 0 }]; }); setSearch(""); setBarcode(""); barcodeRef.current?.focus(); }; const handleBarcode = () => { const code = barcode.trim(); if (!code) return; const product = products.find((item) => item.is_active && (item.barcode === code || item.sku === code)); if (!product) { if (!isAdmin) return toast.error("Produto não encontrado no catálogo."); setMissingBarcode(code); return; } addProduct(product); }; const updateItem = (id: string, field: keyof CartItem, value: string | number) => setCart((current) => current.map((item) => item.productId === id ? { ...item, [field]: field === "quantity" || field === "unitPrice" || field === "discountValue" ? Math.max(0, Number(value)) : value } as CartItem : item)); const finalize = async () => { if (!cart.length) return toast.error("Adicione pelo menos um produto à venda."); if (paymentMethod === "cash" && paymentStatus === "paid" && asNumber(amountReceived) < total) return toast.error("O valor recebido é menor que o total."); setSaving(true); const { data, error } = await localApi.rpc("finalize_sale", { payload: { company_id: company.id, customer_id: customerId || null, status: paymentStatus === "paid" ? "completed" : "pending", payment_method: paymentMethod, general_discount_type: generalType, general_discount_value: asNumber(generalDiscount), received_amount: amountReceived || null, items: cart.map((item) => ({ product_id: item.productId, quantity: item.quantity, discount_type: item.discountType, discount_value: item.discountValue })) } }); setSaving(false); if (error || !data) return toast.error(error?.message || "Não foi possível salvar a venda."); setCart([]); setCustomerId(""); setGeneralDiscount(""); setAmountReceived(""); await onSaved(); toast.success("Venda #" + data.sale_number + " registrada com sucesso."); };; const saveQuickProduct = async (event: React.FormEvent) => { event.preventDefault(); if (!quickForm.name.trim() || !missingBarcode) return toast.error("Informe ao menos o nome do produto."); const result = await localApi.from("products").insert({ company_id: company.id, name: quickForm.name.trim(), barcode: missingBarcode, sale_price: asNumber(quickForm.sale_price), cost_price: asNumber(quickForm.cost_price), stock: asNumber(quickForm.stock), minimum_stock: asNumber(quickForm.minimum_stock), is_active: true }).select("id, company_id, name, barcode, sale_price, stock, minimum_stock, is_active").single(); if (result.error || !result.data) return toast.error(result.error?.code === "23505" ? "Este código já foi cadastrado." : "Não foi possível cadastrar o produto."); setQuickProduct(false); setMissingBarcode(""); setQuickForm({ name: "", sale_price: "", cost_price: "", stock: "", minimum_stock: "" }); addProduct(result.data as Product); await onSaved(); toast.success("Produto cadastrado e adicionado à venda."); }; return <><div className="mb-6 flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p className="mb-2 text-xs font-bold uppercase tracking-[.16em] text-[#0e716b]">Atendimento rápido</p><h2 className="text-2xl font-black tracking-tight sm:text-3xl">Nova venda</h2><p className="mt-2 text-sm text-slate-500">Leia os produtos, ajuste a condição e finalize sem sair da tela.</p></div><Badge variant="outline" className="w-fit rounded-full border-[#c5e4dc] bg-[#effaf6] px-3 py-1.5 text-[#0e716b]"><Zap size={14} className="mr-1.5" /> Caixa pronto</Badge></div><div className="grid gap-6 xl:grid-cols-[1fr_390px]"><div className="space-y-5"><Card className="border-[#9dd3c7] bg-[#f8fffc] shadow-[0_10px_35px_rgba(14,113,107,.08)]"><CardContent className="p-4 sm:p-5"><div className="flex items-center gap-3"><div className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[#0e716b] text-white"><PackageCheck size={20} /></div><div className="flex-1"><Label className="text-xs font-bold uppercase tracking-[.12em] text-[#0e716b]">Código de barras</Label><Input ref={barcodeRef} autoFocus value={barcode} onChange={(event) => setBarcode(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") { event.preventDefault(); handleBarcode(); } }} placeholder="Passe o leitor ou digite o código e pressione Enter" className="mt-1 h-11 border-[#b7ded4] bg-white text-base font-semibold shadow-sm placeholder:font-normal" /></div><div className="hidden text-right text-xs text-slate-400 sm:block"><span className="block font-bold text-[#0e716b]">Leitor USB/HID</span>Pronto para próxima leitura</div></div></CardContent></Card><Card className="border-[#e2ece9] shadow-[0_8px_30px_rgba(20,70,67,.045)]"><CardContent className="p-4 sm:p-5"><div className="relative"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={17} /><Input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Pesquisar produto por nome, código ou SKU" className="h-11 rounded-xl border-[#dceae6] pl-10" />{search && <div className="absolute left-0 right-0 top-14 z-10 overflow-hidden rounded-2xl border border-[#dceae6] bg-white p-2 shadow-xl">{matching.length ? matching.map((product) => <button key={product.id} onClick={() => addProduct(product)} className="flex w-full items-center justify-between rounded-xl px-3 py-3 text-left hover:bg-[#eff8f5]"><span><span className="block text-sm font-bold">{product.name}</span><span className="text-xs text-slate-400">{product.barcode || product.sku || "Sem código"} · estoque {product.stock}</span></span><span className="font-black text-[#0e716b]">{money(product.sale_price)}</span></button>) : <p className="p-3 text-sm text-slate-500">Nenhum produto ativo encontrado.</p>}</div>}</div><div className="mt-5 overflow-x-auto">{cart.length === 0 ? <div className="py-14 text-center"><span className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-[#eff8f5] text-[#0e716b]"><ShoppingCart size={24} /></span><p className="mt-4 font-black">Sua venda está vazia</p><p className="mt-1 text-sm text-slate-400">Use o leitor ou busque um produto para começar.</p></div> : <Table><TableHeader><TableRow className="border-[#edf2f0] hover:bg-transparent"><TableHead className="pl-0 text-[10px] uppercase tracking-wider text-slate-400">Produto</TableHead><TableHead className="text-[10px] uppercase tracking-wider text-slate-400">Qtd.</TableHead><TableHead className="text-[10px] uppercase tracking-wider text-slate-400">Preço</TableHead><TableHead className="text-[10px] uppercase tracking-wider text-slate-400">Desc.</TableHead><TableHead className="text-right text-[10px] uppercase tracking-wider text-slate-400">Total</TableHead><TableHead /></TableRow></TableHeader><TableBody>{cart.map((item) => <TableRow key={item.productId} className="border-[#edf2f0]"><TableCell className="min-w-[180px] pl-0"><p className="font-bold">{item.name}</p><p className="mt-1 font-mono text-[10px] text-slate-400">{item.barcode || "sem código"}</p></TableCell><TableCell><Input aria-label={`Quantidade de ${item.name}`} type="number" min="0.001" step="0.001" value={item.quantity} onChange={(event) => updateItem(item.productId, "quantity", event.target.value)} className="h-9 w-20 rounded-lg" /></TableCell><TableCell><Input aria-label={`Preço de ${item.name}`} type="number" min="0" step="0.01" value={item.unitPrice} onChange={(event) => updateItem(item.productId, "unitPrice", event.target.value)} readOnly={!isAdmin} className="h-9 w-24 rounded-lg" /></TableCell><TableCell><div className="flex gap-1"><select value={item.discountType} onChange={(event) => updateItem(item.productId, "discountType", event.target.value)} disabled={!isAdmin} className="h-9 rounded-lg border border-input bg-background px-1 text-xs"><option value="fixed">R$</option><option value="percent">%</option></select><Input type="number" min="0" value={item.discountValue} onChange={(event) => updateItem(item.productId, "discountValue", event.target.value)} disabled={!isAdmin} className="h-9 w-20 rounded-lg" /></div></TableCell><TableCell className="text-right font-black">{money(itemTotal(item))}</TableCell><TableCell><Button variant="ghost" size="icon" onClick={() => setCart((current) => current.filter((entry) => entry.productId !== item.productId))} className="rounded-lg text-slate-400 hover:bg-[#fff0f1] hover:text-[#be5562]"><Trash2 size={15} /></Button></TableCell></TableRow>)}</TableBody></Table>}</div></CardContent></Card></div><Card className="h-fit border-[#e2ece9] shadow-[0_12px_38px_rgba(20,70,67,.07)] xl:sticky xl:top-24"><CardHeader className="border-b border-[#edf2f0] pb-4"><CardTitle className="flex items-center gap-2 text-base font-black"><ReceiptText size={18} className="text-[#0e716b]" /> Resumo da venda</CardTitle></CardHeader><CardContent className="space-y-5 p-5"><div className="flex items-end gap-2"><div className="min-w-0 flex-1"><Field label="Cliente"><select value={customerId} onChange={(event) => setCustomerId(event.target.value)} className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="">Consumidor final</option>{customerOptions.filter((customer) => customer.is_active).map((customer) => <option key={customer.id} value={customer.id}>{customer.name}</option>)}</select></Field></div><Button type="button" variant="outline" onClick={() => setNewCustomerOpen(true)} className="h-10 shrink-0 rounded-xl border-[#cbe4dc] px-3 text-[#0e716b]" title="Cadastrar cliente"><Plus size={16} /></Button></div><div className="rounded-2xl bg-[#f3f8f6] p-4"><div className="flex justify-between text-sm text-slate-500"><span>Subtotal</span><span>{money(subtotal)}</span></div><div className="mt-2 flex justify-between text-sm text-slate-500"><span>Descontos nos itens</span><span className="text-[#be5562]">- {money(productDiscount)}</span></div><div className="mt-3 flex items-center justify-between border-t border-[#dfece7] pt-3"><span className="text-xs font-bold uppercase tracking-wide text-slate-500">Desconto geral</span><div className="flex gap-1"><select value={generalType} onChange={(event) => setGeneralType(event.target.value as "fixed" | "percent")} disabled={!isAdmin} className="h-8 rounded-lg border border-[#d6e7e1] bg-white px-1 text-xs"><option value="fixed">R$</option><option value="percent">%</option></select><Input type="number" min="0" value={generalDiscount} onChange={(event) => setGeneralDiscount(event.target.value)} disabled={!isAdmin} className="h-8 w-20 rounded-lg bg-white text-right" /></div></div><div className="mt-4 flex items-end justify-between"><span className="font-black">Total</span><span className="text-3xl font-black tracking-tight text-[#0e716b]">{money(total)}</span></div></div><Field label="Forma de pagamento"><select value={paymentMethod} onChange={(event) => setPaymentMethod(event.target.value)} className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm">{Object.entries(paymentLabels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></Field><Field label="Status"><select value={paymentStatus} onChange={(event) => setPaymentStatus(event.target.value)} className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="paid">Pago</option><option value="pending">Pendente</option></select></Field>{paymentMethod === "cash" && paymentStatus === "paid" && <div className="grid grid-cols-2 gap-3"><Field label="Valor recebido"><Input type="number" min="0" step="0.01" value={amountReceived} onChange={(event) => setAmountReceived(event.target.value)} placeholder={String(total)} /></Field><div className="rounded-xl bg-[#e9f7f1] p-3"><p className="text-[10px] font-bold uppercase tracking-wide text-[#0e716b]">Troco</p><p className="mt-2 text-lg font-black text-[#14745f]">{money(change)}</p></div></div>}<Button onClick={finalize} disabled={saving || !cart.length} className="h-12 w-full rounded-xl bg-[#0e716b] font-black shadow-[0_10px_20px_rgba(14,113,107,.2)] hover:bg-[#0e4f50]">{saving ? "Registrando..." : "Finalizar venda"}<ArrowUpRight size={17} className="ml-2" /></Button>{isAdmin && <button onClick={() => navigate("/produtos")} className="flex w-full items-center justify-center gap-2 text-xs font-bold text-[#0e716b] hover:underline"><Plus size={14} /> Cadastrar produto no catálogo</button>}</CardContent></Card></div><NewCustomerDialog company={company} open={newCustomerOpen} onOpenChange={setNewCustomerOpen} onCreated={async (customer) => { setCustomerOptions((current) => current.some((entry) => entry.id === customer.id) ? current : [...current, customer]); setCustomerId(customer.id); await onSaved(); }} /><Dialog open={Boolean(missingBarcode)} onOpenChange={(open) => !open && setMissingBarcode("")}><DialogContent className="rounded-3xl border-[#dceae6]"><DialogHeader><DialogTitle className="font-black">Produto não encontrado</DialogTitle><DialogDescription>O código <strong className="font-mono text-[#0e716b]">{missingBarcode}</strong> ainda não está cadastrado nesta empresa.</DialogDescription></DialogHeader><DialogFooter><Button variant="ghost" onClick={() => setMissingBarcode("")} className="rounded-xl">Cancelar</Button><Button onClick={() => { setQuickForm({ ...quickForm }); setQuickProduct(true); }} className="rounded-xl bg-[#0e716b] hover:bg-[#0e4f50]">Cadastrar produto</Button></DialogFooter></DialogContent></Dialog><Dialog open={quickProduct} onOpenChange={setQuickProduct}><DialogContent className="rounded-3xl border-[#dceae6]"><DialogHeader><DialogTitle className="font-black">Cadastro rápido</DialogTitle><DialogDescription>O produto será salvo e adicionado automaticamente à venda.</DialogDescription></DialogHeader><form onSubmit={saveQuickProduct} className="grid gap-4 sm:grid-cols-2"><div className="sm:col-span-2"><Field label="Código de barras"><Input value={missingBarcode} disabled /></Field></div><Field label="Nome" required><Input autoFocus value={quickForm.name} onChange={(event) => setQuickForm({ ...quickForm, name: event.target.value })} /></Field><Field label="Preço de venda"><Input type="number" min="0" step="0.01" value={quickForm.sale_price} onChange={(event) => setQuickForm({ ...quickForm, sale_price: event.target.value })} /></Field><Field label="Preço de custo"><Input type="number" min="0" step="0.01" value={quickForm.cost_price} onChange={(event) => setQuickForm({ ...quickForm, cost_price: event.target.value })} /></Field><Field label="Estoque inicial"><Input type="number" min="0" step="0.001" value={quickForm.stock} onChange={(event) => setQuickForm({ ...quickForm, stock: event.target.value })} /></Field><DialogFooter className="sm:col-span-2"><Button type="submit" className="w-full rounded-xl bg-[#0e716b] hover:bg-[#0e4f50]">Cadastrar e adicionar à venda</Button></DialogFooter></form></DialogContent></Dialog></>;
}

function FinanceView({ company, finance, onSaved }: { company: Company; finance: Finance[]; onSaved: () => Promise<void> }) { const [open, setOpen] = useState(false); const [form, setForm] = useState({ type: "expense", category: "Despesa", description: "", amount: "", status: "paid" }); const income = finance.filter((item) => item.type === "income" && item.status !== "cancelled").reduce((sum, item) => sum + asNumber(item.amount), 0); const expense = finance.filter((item) => item.type === "expense" && item.status !== "cancelled").reduce((sum, item) => sum + asNumber(item.amount), 0); const save = async (event: React.FormEvent) => { event.preventDefault(); if (asNumber(form.amount) <= 0) return toast.error("Informe um valor válido."); const user = (await localApi.auth.getUser()).data.user; const { error } = await localApi.from("financial_transactions").insert({ ...form, company_id: company.id, amount: asNumber(form.amount), created_by: user?.id }); if (error) return toast.error("Não foi possível salvar o lançamento."); setOpen(false); setForm({ type: "expense", category: "Despesa", description: "", amount: "", status: "paid" }); toast.success("Lançamento financeiro salvo."); await onSaved(); }; return <><PageIntro eyebrow="Fluxo de caixa" title="Financeiro" description="Acompanhe entradas de vendas e registre despesas para entender o resultado do período." action={<Button onClick={() => setOpen(true)} className="h-11 rounded-xl bg-[#0e716b] font-bold hover:bg-[#0e4f50]"><Plus size={18} className="mr-2" /> Novo lançamento</Button>} /><div className="mb-6 grid gap-4 sm:grid-cols-3"><StatCard label="Entradas" value={money(income)} detail="vendas e receitas" icon={ArrowUpRight} /><StatCard label="Saídas" value={money(expense)} detail="despesas registradas" icon={ArrowDownRight} tone="orange" /><StatCard label="Resultado" value={money(income - expense)} detail="entradas menos saídas" icon={TrendingUp} tone="blue" /></div><Card className="border-[#e2ece9] shadow-[0_8px_30px_rgba(20,70,67,.045)]"><CardHeader><CardTitle className="text-base font-black">Lançamentos recentes</CardTitle></CardHeader><CardContent className="p-0"><div className="overflow-x-auto"><Table><TableHeader><TableRow className="border-[#edf2f0] hover:bg-transparent"><TableHead className="pl-6 text-[10px] uppercase tracking-wider text-slate-400">Data</TableHead><TableHead className="text-[10px] uppercase tracking-wider text-slate-400">Descrição</TableHead><TableHead className="text-[10px] uppercase tracking-wider text-slate-400">Categoria</TableHead><TableHead className="text-[10px] uppercase tracking-wider text-slate-400">Status</TableHead><TableHead className="pr-6 text-right text-[10px] uppercase tracking-wider text-slate-400">Valor</TableHead></TableRow></TableHeader><TableBody>{finance.map((item) => <TableRow key={item.id} className="border-[#edf2f0]"><TableCell className="pl-6 text-xs text-slate-500">{dateOnly(item.occurred_at)}</TableCell><TableCell className="font-semibold">{item.description || "Sem descrição"}</TableCell><TableCell className="text-sm text-slate-500">{item.category}</TableCell><TableCell><StatusBadge status={item.status} /></TableCell><TableCell className={`pr-6 text-right font-black ${item.type === "income" ? "text-[#14745f]" : "text-[#be5562]"}`}>{item.type === "income" ? "+" : "-"}{money(item.amount)}</TableCell></TableRow>)}{finance.length === 0 && <TableRow><TableCell colSpan={5} className="py-14 text-center text-sm text-slate-400">Os lançamentos financeiros aparecerão aqui.</TableCell></TableRow>}</TableBody></Table></div></CardContent></Card><Dialog open={open} onOpenChange={setOpen}><DialogContent className="rounded-3xl border-[#dceae6]"><DialogHeader><DialogTitle className="font-black">Novo lançamento</DialogTitle><DialogDescription>Use para registrar despesas ou receitas que não vieram de uma venda.</DialogDescription></DialogHeader><form onSubmit={save} className="space-y-4"><Field label="Tipo"><select value={form.type} onChange={(event) => setForm({ ...form, type: event.target.value })} className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="expense">Saída</option><option value="income">Entrada</option></select></Field><Field label="Categoria"><Input value={form.category} onChange={(event) => setForm({ ...form, category: event.target.value })} placeholder="Ex.: fornecedor, frete, anúncios" /></Field><Field label="Descrição"><Input value={form.description} onChange={(event) => setForm({ ...form, description: event.target.value })} /></Field><Field label="Valor"><Input type="number" min="0.01" step="0.01" value={form.amount} onChange={(event) => setForm({ ...form, amount: event.target.value })} /></Field><Field label="Status"><select value={form.status} onChange={(event) => setForm({ ...form, status: event.target.value })} className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="paid">Pago</option><option value="pending">Pendente</option></select></Field><DialogFooter><Button type="submit" className="w-full rounded-xl bg-[#0e716b] hover:bg-[#0e4f50]">Salvar lançamento</Button></DialogFooter></form></DialogContent></Dialog></>; }

function QuotesView({ company, quotes, customers, products, onSaved, onConvert }: { company: Company; quotes: Quote[]; customers: Customer[]; products: Product[]; onSaved: () => Promise<void>; onConvert: (path: string) => void }) { const [open, setOpen] = useState(false); const [form, setForm] = useState({ customer_id: "", product_id: "", quantity: "1", unit_price: "", discount: "", notes: "" }); const product = products.find((item) => item.id === form.product_id); const total = Math.max(0, asNumber(form.quantity) * asNumber(form.unit_price || product?.sale_price) - asNumber(form.discount)); const save = async (event: React.FormEvent) => { event.preventDefault(); if (!product || asNumber(form.quantity) <= 0) return toast.error("Selecione um produto e informe a quantidade."); const user = (await localApi.auth.getUser()).data.user; const quoteResult = await localApi.from("quotes").insert({ company_id: company.id, customer_id: form.customer_id || null, subtotal: asNumber(form.quantity) * asNumber(form.unit_price || product.sale_price), discount: asNumber(form.discount), total, notes: form.notes, created_by: user?.id }).select().single(); if (quoteResult.error || !quoteResult.data) return toast.error("Não foi possível criar o orçamento."); const { error } = await localApi.from("quote_items").insert({ quote_id: quoteResult.data.id, product_id: product.id, product_name: product.name, quantity: asNumber(form.quantity), unit_price: asNumber(form.unit_price || product.sale_price), discount: asNumber(form.discount), total }); if (error) return toast.error("Não foi possível salvar os itens do orçamento."); setOpen(false); setForm({ customer_id: "", product_id: "", quantity: "1", unit_price: "", discount: "", notes: "" }); toast.success(`Orçamento #${quoteResult.data.quote_number} criado.`); await onSaved(); }; const convert = async (quote: Quote) => { const { data: items } = await localApi.from("quote_items").select("*").eq("quote_id", quote.id); if (!items?.length) return toast.error("Este orçamento não possui itens."); const cart = items.map((item) => ({ productId: item.product_id, name: item.product_name, quantity: item.quantity, unitPrice: item.unit_price, costPrice: products.find((entry) => entry.id === item.product_id)?.cost_price || 0, barcode: products.find((entry) => entry.id === item.product_id)?.barcode || null, discountType: "fixed" as const, discountValue: item.discount })); sessionStorage.setItem("controlavenda_quote_cart", JSON.stringify({ quoteId: quote.id, customerId: quote.customer_id, cart })); onConvert("/vendas/nova"); toast.success("Itens copiados. Revise e finalize a venda."); }; return <><PageIntro eyebrow="Propostas comerciais" title="Orçamentos" description="Crie propostas sem baixar estoque e transforme-as em vendas quando o cliente aprovar." action={<Button onClick={() => setOpen(true)} className="h-11 rounded-xl bg-[#0e716b] font-bold hover:bg-[#0e4f50]"><Plus size={18} className="mr-2" /> Novo orçamento</Button>} /><Card className="border-[#e2ece9] shadow-[0_8px_30px_rgba(20,70,67,.045)]"><CardContent className="p-0"><div className="overflow-x-auto"><Table><TableHeader><TableRow className="border-[#edf2f0] hover:bg-transparent"><TableHead className="pl-6 text-[10px] uppercase tracking-wider text-slate-400">Número</TableHead><TableHead className="text-[10px] uppercase tracking-wider text-slate-400">Cliente</TableHead><TableHead className="text-[10px] uppercase tracking-wider text-slate-400">Data</TableHead><TableHead className="text-[10px] uppercase tracking-wider text-slate-400">Status</TableHead><TableHead className="pr-6 text-right text-[10px] uppercase tracking-wider text-slate-400">Total</TableHead><TableHead /></TableRow></TableHeader><TableBody>{quotes.map((quote) => <TableRow key={quote.id} className="border-[#edf2f0]"><TableCell className="pl-6 font-bold text-[#0e716b]">#{quote.quote_number}</TableCell><TableCell className="font-semibold">{quote.customers?.name || "Consumidor final"}</TableCell><TableCell className="text-xs text-slate-500">{dateOnly(quote.created_at)}</TableCell><TableCell><StatusBadge status={quote.status} /></TableCell><TableCell className="pr-6 text-right font-black">{money(quote.total)}</TableCell><TableCell><Button onClick={() => convert(quote)} variant="outline" className="rounded-xl border-[#cbe4dc] text-xs font-bold text-[#0e716b] hover:bg-[#eff8f5]">Transformar em venda</Button></TableCell></TableRow>)}{quotes.length === 0 && <TableRow><TableCell colSpan={6} className="py-14 text-center text-sm text-slate-400">Crie seu primeiro orçamento para começar.</TableCell></TableRow>}</TableBody></Table></div></CardContent></Card><Dialog open={open} onOpenChange={setOpen}><DialogContent className="rounded-3xl border-[#dceae6]"><DialogHeader><DialogTitle className="font-black">Novo orçamento</DialogTitle><DialogDescription>O estoque só será alterado quando você transformar em venda.</DialogDescription></DialogHeader><form onSubmit={save} className="space-y-4"><Field label="Cliente"><select value={form.customer_id} onChange={(event) => setForm({ ...form, customer_id: event.target.value })} className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="">Consumidor final</option>{customers.filter((customer) => customer.is_active).map((customer) => <option key={customer.id} value={customer.id}>{customer.name}</option>)}</select></Field><Field label="Produto" required><select value={form.product_id} onChange={(event) => setForm({ ...form, product_id: event.target.value, unit_price: products.find((item) => item.id === event.target.value)?.sale_price.toString() || "" })} className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="">Selecione um produto</option>{products.filter((item) => item.is_active).map((item) => <option key={item.id} value={item.id}>{item.name} · {money(item.sale_price)}</option>)}</select></Field><div className="grid grid-cols-3 gap-3"><Field label="Quantidade"><Input type="number" min="1" value={form.quantity} onChange={(event) => setForm({ ...form, quantity: event.target.value })} /></Field><Field label="Preço unitário"><Input type="number" min="0" step="0.01" value={form.unit_price} onChange={(event) => setForm({ ...form, unit_price: event.target.value })} /></Field><Field label="Desconto"><Input type="number" min="0" step="0.01" value={form.discount} onChange={(event) => setForm({ ...form, discount: event.target.value })} /></Field></div><div className="rounded-xl bg-[#eff8f5] p-3 text-right"><span className="text-xs font-bold uppercase tracking-wide text-slate-500">Total estimado</span><p className="text-xl font-black text-[#0e716b]">{money(total)}</p></div><Field label="Observações"><Textarea value={form.notes} onChange={(event) => setForm({ ...form, notes: event.target.value })} /></Field><DialogFooter><Button type="submit" className="w-full rounded-xl bg-[#0e716b] hover:bg-[#0e4f50]">Salvar orçamento</Button></DialogFooter></form></DialogContent></Dialog></>; }

function ReportsView({ company, products, sales, finance, customers }: { company: Company; products: Product[]; sales: Sale[]; finance: Finance[]; customers: Customer[] }) { const activeSales = sales.filter((sale) => sale.status !== "cancelled"); const revenue = activeSales.reduce((sum, sale) => sum + asNumber(sale.total), 0); const byPayment = Object.entries(activeSales.reduce<Record<string, number>>((acc, sale) => { acc[sale.payment_method] = (acc[sale.payment_method] || 0) + asNumber(sale.total); return acc; }, {})); const topProducts = products.filter((product) => product.is_active).sort((a, b) => b.sale_price - a.sale_price).slice(0, 5); return <><PageIntro eyebrow="Visão analítica" title="Relatórios" description="Indicadores calculados a partir dos registros atuais de vendas, estoque e financeiro." action={<Button onClick={() => downloadReportPdf(company, products, sales, finance, customers)} variant="outline" className="h-11 rounded-xl border-[#cbe4dc] font-bold text-[#0e716b] hover:bg-[#eff8f5]"><Download size={17} className="mr-2" /> Baixar relatório PDF</Button>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Faturamento" value={money(revenue)} detail={`${activeSales.length} vendas válidas`} icon={CircleDollarSign} /><StatCard label="Ticket médio" value={money(activeSales.length ? revenue / activeSales.length : 0)} detail="média por venda" icon={ReceiptText} tone="blue" /><StatCard label="Produtos ativos" value={String(products.filter((product) => product.is_active).length)} detail={`${products.filter((product) => product.stock <= 0).length} sem estoque`} icon={Package} tone="orange" /><StatCard label="Base de clientes" value={String(customers.length)} detail="cadastros na empresa" icon={Users} tone="rose" /></div><div className="mt-6 grid gap-6 lg:grid-cols-2"><Card className="border-[#e2ece9] shadow-[0_8px_30px_rgba(20,70,67,.045)]"><CardHeader><CardTitle className="text-base font-black">Vendas por forma de pagamento</CardTitle></CardHeader><CardContent className="space-y-3">{byPayment.map(([method, value]) => <div key={method} className="flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-xl bg-[#e9efff] text-[#496bc0]"><CreditCard size={17} /></span><span className="flex-1 text-sm font-bold">{paymentLabels[method] || method}</span><span className="font-black">{money(value)}</span></div>)}{byPayment.length === 0 && <p className="py-10 text-center text-sm text-slate-400">Os dados aparecerão após as primeiras vendas.</p>}</CardContent></Card><Card className="border-[#e2ece9] shadow-[0_8px_30px_rgba(20,70,67,.045)]"><CardHeader><CardTitle className="text-base font-black">Produtos em atenção</CardTitle></CardHeader><CardContent className="space-y-3">{topProducts.map((product) => <div key={product.id} className="flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-xl bg-[#eff8f5] text-[#0e716b]"><Package size={17} /></span><span className="flex-1"><span className="block text-sm font-bold">{product.name}</span><span className="text-xs text-slate-400">custo {money(product.cost_price)}</span></span><span className="text-right"><span className="block font-black">{money(product.sale_price)}</span><span className={`text-xs font-bold ${product.stock <= product.minimum_stock ? "text-[#ae5d28]" : "text-[#14745f]"}`}>{product.stock} em estoque</span></span></div>)}{topProducts.length === 0 && <p className="py-10 text-center text-sm text-slate-400">Cadastre produtos para acompanhar indicadores.</p>}</CardContent></Card></div><Card className="mt-6 border-[#e2ece9] shadow-[0_8px_30px_rgba(20,70,67,.045)]"><CardHeader><CardTitle className="text-base font-black">Resumo de lançamentos financeiros</CardTitle></CardHeader><CardContent><div className="grid gap-3 sm:grid-cols-3"><div className="rounded-2xl bg-[#eaf8f2] p-4"><p className="text-xs font-bold uppercase tracking-wide text-[#14745f]">Entradas</p><p className="mt-2 text-xl font-black text-[#14745f]">{money(finance.filter((item) => item.type === "income").reduce((sum, item) => sum + asNumber(item.amount), 0))}</p></div><div className="rounded-2xl bg-[#fff0e3] p-4"><p className="text-xs font-bold uppercase tracking-wide text-[#ae5d28]">Saídas</p><p className="mt-2 text-xl font-black text-[#ae5d28]">{money(finance.filter((item) => item.type === "expense").reduce((sum, item) => sum + asNumber(item.amount), 0))}</p></div><div className="rounded-2xl bg-[#e9efff] p-4"><p className="text-xs font-bold uppercase tracking-wide text-[#496bc0]">Pendentes</p><p className="mt-2 text-xl font-black text-[#496bc0]">{money(finance.filter((item) => item.status === "pending").reduce((sum, item) => sum + asNumber(item.amount), 0))}</p></div></div></CardContent></Card></>; }

function SettingsView({ company, onSaved }: { company: Company; onSaved: (company: Company) => void }) { const [form, setForm] = useState(company); const [saving, setSaving] = useState(false); useEffect(() => setForm(company), [company]); const save = async (event: React.FormEvent) => { event.preventDefault(); setSaving(true); const { data, error } = await localApi.from("companies").update({ name: form.name, phone: form.phone, whatsapp: form.whatsapp, address: form.address, address_number: form.address_number, city: form.city, state: form.state, zip_code: form.zip_code, tax_id: form.tax_id, notes: form.notes, allow_negative_stock: form.allow_negative_stock, updated_at: new Date().toISOString() }).eq("id", company.id).select().single(); setSaving(false); if (error || !data) return toast.error("Não foi possível salvar as configurações."); onSaved(data as Company); }; return <><PageIntro eyebrow="Sua operação" title="Configurações" description="Esses dados serão usados nos documentos, orçamentos e identificação da empresa." /><Card className="max-w-4xl border-[#e2ece9] shadow-[0_8px_30px_rgba(20,70,67,.045)]"><CardHeader><CardTitle className="flex items-center gap-2 text-base font-black"><Store size={18} className="text-[#0e716b]" /> Dados da empresa</CardTitle></CardHeader><CardContent><form onSubmit={save} className="grid gap-5 sm:grid-cols-2"><Field label="Nome da empresa" required><Input value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} /></Field><Field label="CNPJ / CPF"><Input value={form.tax_id || ""} onChange={(event) => setForm({ ...form, tax_id: event.target.value })} /></Field><Field label="Telefone"><Input value={form.phone || ""} onChange={(event) => setForm({ ...form, phone: event.target.value })} /></Field><Field label="WhatsApp"><Input value={form.whatsapp || ""} onChange={(event) => setForm({ ...form, whatsapp: event.target.value })} /></Field><Field label="Endereço"><Input value={form.address || ""} onChange={(event) => setForm({ ...form, address: event.target.value })} /></Field><Field label="Número"><Input value={form.address_number || ""} onChange={(event) => setForm({ ...form, address_number: event.target.value })} /></Field><Field label="Cidade"><Input value={form.city || ""} onChange={(event) => setForm({ ...form, city: event.target.value })} /></Field><Field label="Estado"><Input maxLength={2} value={form.state || ""} onChange={(event) => setForm({ ...form, state: event.target.value.toUpperCase() })} /></Field><Field label="CEP"><Input value={form.zip_code || ""} onChange={(event) => setForm({ ...form, zip_code: event.target.value })} /></Field><div className="flex items-end pb-1"><label className="flex items-center gap-3 text-sm font-semibold text-slate-600"><input type="checkbox" checked={form.allow_negative_stock} onChange={(event) => setForm({ ...form, allow_negative_stock: event.target.checked })} className="h-4 w-4 rounded border-[#b9d8d0] accent-[#0e716b]" /> Permitir estoque negativo</label></div><div className="sm:col-span-2"><Field label="Observações padrão para documentos"><Textarea value={form.notes || ""} onChange={(event) => setForm({ ...form, notes: event.target.value })} className="min-h-24" /></Field></div><div className="flex justify-end sm:col-span-2"><Button disabled={saving} type="submit" className="h-11 rounded-xl bg-[#0e716b] px-6 font-bold hover:bg-[#0e4f50]">{saving ? "Salvando..." : "Salvar configurações"}</Button></div></form></CardContent></Card></>; }
